import com.google.gson.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Real generated Trainers reuse reviewed player actions without adopting attack semantics. */
public final class GeneratedRuleBatch23Test {
    static final UUID A=GeneratedRuleBatch19Test.A,B=GeneratedRuleBatch19Test.B;
    static final Ruleset RULES=GeneratedRuleBatch19Test.RULES;
    static void check(boolean ok,String why){GeneratedRuleBatch8Test.check(ok,why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static UUID bench(ServerMatch m,UUID p){return m.benchPokemonView(p).getFirst().pokemonId();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return GeneratedRuleBatch13Test.hand(m,p,id);}
    static ServerMatch game(String id){return game(id,0,EnergyType.WATER);}
    static ServerMatch game(String id,int seed,EnergyType energy){return fixture(GeneratedRuleBatch8Test.trainer(id),seed,energy);}
    static void play(ServerMatch m){m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);}
    static void cards(ServerMatch m,List<UUID> ids){var p=m.effectCardPrompt(A);m.submitEffectCards(A,p.resolutionId(),p.step(),ids);if(m.effectCardReveal()!=null)m.acknowledgeEffectReveal(B,m.effectCardReveal().id());}
    static int coinResult(ServerMatch m,int before){return m.randomTranscript().subList(before,m.randomTranscript().size()).stream().filter(e->e.operation().startsWith("effect-coin:")).reduce((a,b)->b).orElseThrow().result();}
    public static void main(String[] args){forceSwitch();searches();statuses();healing();discardEnergy();recovery();mars();drawCoins();shuffleCoin();attachments();coinSearches();mill();System.out.println("GeneratedRuleBatch23Test passed: real Trainer limits, actual draw binding, controlled switch ownership, private search/reveal, coin branches, shuffle order, physical attachments, discard and healing");}
    static void forceSwitch(){for(String id:List.of("me1_en_126","sv3_en_194")){var m=game(id);int size=m.privateView(A).hand().size();UUID replacement=bench(m,B);play(m);var p=m.effectPokemonPrompt(B);reject(()->m.chooseEffectPokemon(A,p.resolutionId(),p.step(),replacement));m.chooseEffectPokemon(B,p.resolutionId(),p.step(),replacement);check(active(m,B).equals(replacement)&&m.privateView(A).hand().size()==size-1+(id.startsWith("sv")?3:0),"Forced switch owner or preceding draw lost");}}
    static void searches(){for(String id:List.of("sm6_en_109","swsh2_en_156","sm8_en_167","sm11_en_202","xy8_en_148","xy5_en_125","swsh12_en_159")){EnergyType type=id.equals("swsh12_en_159")?EnergyType.DRAGON:EnergyType.WATER;var m=game(id,0,type);m.drawCardsByEffect(A,A,m.privateView(A).deck().size());var seed=List.of(hand(m,A,"energy").instanceId(),hand(m,A,"special").instanceId(),hand(m,A,"basic").instanceId(),hand(m,A,"tool").instanceId(),hand(m,A,"supporter").instanceId(),hand(m,A,"stadium").instanceId(),hand(m,A,"item").instanceId());m.discardHandCardsByEffect(A,A,seed);m.shuffleDiscardIntoDeckByEffect(A,A);play(m);var p=m.effectCardPrompt(A);check(p.minimum()==0,"Private deck search required disclosure");Set<String> kinds=new HashSet<>(p.candidates().stream().map(CardInstance::definitionId).toList());Set<String> expected=id.equals("sm6_en_109")||id.equals("swsh2_en_156")?Set.of("energy"):id.equals("sm8_en_167")?Set.of("tool"):id.equals("sm11_en_202")?Set.of("supporter"):id.equals("xy8_en_148")?Set.of("tool","supporter","stadium","item"):Set.of("basic");check(kinds.equals(expected),"Trainer search category/type mismatch "+id+" "+kinds);check(m.clientView(B).effectSelection()==null,"Private deck search leaked to opponent");var selected=p.candidates().getFirst();cards(m,List.of(selected.instanceId()));check(m.privateView(A).hand().contains(selected)&&!m.hasPendingEffectChoice(),"Selected card did not reveal/return to hand");}}
    static void statuses(){for(String id:List.of("sm10_en_177","sv6-5_en_058","swsh3_en_173")){var m=game(id);play(m);var expected=id.equals("sm10_en_177")?Set.of(SpecialCondition.POISONED,SpecialCondition.CONFUSED):id.equals("sv6-5_en_058")?Set.of(SpecialCondition.BURNED,SpecialCondition.CONFUSED):Set.of(SpecialCondition.CONFUSED);check(m.activePokemonView(B).conditions().containsAll(expected)&&m.activePokemonView(A).conditions().contains(SpecialCondition.CONFUSED)==id.equals("swsh3_en_173"),"Trainer statuses adopted attack targets or omitted condition");check(m.activePokemonView(B).damage()==0,"Trainer status incorrectly ran Pokemon Checkup");}}
    static void healing(){for(boolean both:List.of(false,true)){var m=game(both?"sv1_en_184":"swsh9_en_139");for(UUID player:List.of(A,B)){m.placeDamageCountersByEffect(A,player,active(m,player),4);m.placeDamageCountersByEffect(A,player,bench(m,player),4);}play(m);int own=both?10:20;check(m.activePokemonView(A).damage()==own&&m.benchPokemonView(A).getFirst().damage()==own&&m.activePokemonView(B).damage()==(both?10:40),"Whole-field Trainer heal owner/quantity");}}
    static void discardEnergy(){var m=game("xy1_en_129");var special=hand(m,B,"special");m.attachEnergyByEffect(A,B,EffectSourceZone.HAND,special.instanceId(),B,active(m,B));play(m);var p=m.effectCardPrompt(A);check(p.minimum()==1&&p.candidates().equals(List.of(special)),"Team Flare Grunt should choose one attached physical Energy");cards(m,List.of(special.instanceId()));check(m.privateView(B).discard().contains(special)&&m.activePokemonView(B).attachedEnergyIds().isEmpty(),"Discarded Energy owner/identity");reject(()->m.playTrainer(A,hand(m,A,"trainer").instanceId(),null));}
    static void recovery(){for(boolean draw:List.of(false,true)){var m=game(draw?"sv4_en_173":"xy4_en_109");var wanted=hand(m,A,draw?"energy":"supporter");var wrong=hand(m,A,"special");m.discardHandCardsByEffect(A,A,List.of(wanted.instanceId(),wrong.instanceId()));int size=m.privateView(A).hand().size();play(m);var p=m.effectCardPrompt(A);check(p.candidates().equals(List.of(wanted))&&p.minimum()==1,"Recovery omitted category/Basic identity");cards(m,List.of(wanted.instanceId()));check(m.privateView(A).hand().size()==size+(draw?2:0)&&m.privateView(A).discard().contains(wrong),"Recovery draw order/identity");}}
    static void mars(){for(int left:List.of(0,1,2)){var m=game("sm5_en_128");m.drawCardsByEffect(A,A,m.privateView(A).deck().size()-left);int before=m.privateView(B).hand().size();var card=hand(m,A,"trainer");if(left==0){reject(()->m.playTrainer(A,card.instanceId(),null));check(m.privateView(A).hand().contains(card)&&m.privateView(B).hand().size()==before,"No-draw Mars paid card or discarded opponent");continue;}m.playTrainer(A,card.instanceId(),null);check(m.privateView(B).hand().size()==before-1&&m.privateView(A).deck().isEmpty(),"Mars did not bind actual partial draw before random discard");}}
    static void drawCoins(){for(String id:List.of("xy1_en_125","svbsp_en_114")){boolean heads=false,tails=false;for(int seed=0;seed<40&&!(heads&&tails);seed++){var m=game(id,seed,EnergyType.WATER);int size=m.privateView(A).hand().size(),rng=m.randomTranscript().size();play(m);boolean head=coinResult(m,rng)==0;heads|=head;tails|=!head;int drawn=id.equals("xy1_en_125")?(head?3:0):(head?4:2);check(m.privateView(A).hand().size()==size-1+drawn&&m.randomTranscript().size()==rng+1,"Trainer coin draw branch/count mismatch");}check(heads&&tails,"Trainer coin outcomes incomplete "+id);}}
    static void shuffleCoin(){boolean heads=false,tails=false;for(int seed=0;seed<40&&!(heads&&tails);seed++){var m=game("sv8_en_173",seed,EnergyType.WATER);m.drawCardsByEffect(A,A,m.privateView(A).deck().size());var trainer=hand(m,A,"trainer");int rng=m.randomTranscript().size();play(m);boolean head=coinResult(m,rng)==0;heads|=head;tails|=!head;check(m.privateView(A).hand().size()==(head?8:3)&&m.privateView(A).discard().contains(trainer)&&!m.privateView(A).deck().contains(trainer),"Drasna did not shuffle before drawing or shuffled its source card");}check(heads&&tails,"Shuffle coin outcomes incomplete");}
    static void attachments(){var m=game("swsh1_en_157");play(m);if(m.hasPendingPokemonSelection()){var p=m.effectPokemonPrompt(A);m.chooseEffectPokemon(A,p.resolutionId(),p.step(),bench(m,A));}var p=m.effectCardPrompt(A);check(p.candidates().stream().allMatch(c->m.cardDefinition(c.definitionId()).basicEnergy()),"Bede allowed Special Energy");UUID energy=p.candidates().getFirst().instanceId();cards(m,List.of(energy));var q=m.effectAttachmentPrompt(A);check(q.targets().equals(List.of(bench(m,A))),"Bede destination not own Bench");m.chooseEffectAttachmentTarget(A,q.resolutionId(),q.step(),bench(m,A));check(!m.energyAttached(A)&&m.benchPokemonView(A).getFirst().attachedEnergyIds().contains(energy),"Bede spent normal attachment");}
    static void coinSearches(){for(String id:List.of("sm5_en_131","sm11_en_208","me3_en_082","sv3-5_en_159")){boolean heads=false,tails=false;for(int seed=0;seed<45&&!(heads&&tails);seed++){var m=game(id,seed,EnergyType.WATER);if(id.equals("sv3-5_en_159")){m.discardHandCardsByEffect(A,A,List.of(hand(m,A,"energy").instanceId(),hand(m,A,"special").instanceId()));}if(id.equals("sm5_en_131")||id.equals("sm11_en_208")){m.drawCardsByEffect(A,A,m.privateView(A).deck().size());var eligible=hand(m,A,id.equals("sm5_en_131")?"item":"stadium");m.discardHandCardsByEffect(A,A,List.of(eligible.instanceId()));m.shuffleDiscardIntoDeckByEffect(A,A);}UUID oldActive=active(m,B);int rng=m.randomTranscript().size();play(m);long count=m.randomTranscript().subList(rng,m.randomTranscript().size()).stream().filter(e->e.operation().startsWith("effect-coin:")&&e.result()==0).count();heads|=count>0;tails|=count==0;int prompts=0;while(m.hasPendingEffectChoice()){
            if(m.hasPendingPokemonSelection()){var p=m.effectPokemonPrompt(A);UUID target=id.equals("me3_en_082")?bench(m,B):bench(m,A);reject(()->m.chooseEffectPokemon(B,p.resolutionId(),p.step(),target));m.chooseEffectPokemon(A,p.resolutionId(),p.step(),target);}
            else if(m.hasPendingAttachmentTarget()){var q=m.effectAttachmentPrompt(A);check(q.targets().equals(List.of(bench(m,A))),"Coin attachment not own Bench");m.chooseEffectAttachmentTarget(A,q.resolutionId(),q.step(),bench(m,A));}
            else if(m.hasPendingCardSelection()){var p=m.effectCardPrompt(A);if(id.equals("sv3-5_en_159")){check(p.candidates().size()==1&&p.candidates().getFirst().definitionId().equals("energy"),"Energy Sticker took Special Energy");cards(m,List.of(p.candidates().getFirst().instanceId()));}else{String kind=id.equals("sm5_en_131")?"item":"stadium";check(p.candidates().stream().allMatch(c->(c.definitionId().equals(kind)||kind.equals("item")&&c.definitionId().equals("trainer"))),"Coin search category "+id+" "+p.candidates());cards(m,List.of());prompts++;}}
            else throw new AssertionError("Unexpected coin continuation "+id);
        }if(id.equals("sm11_en_208")||id.equals("sm5_en_131"))check(prompts==count,"Search prompt count differs from heads");if(id.equals("me3_en_082"))check(active(m,B).equals(oldActive)==(count==0),"Catcher outcome did not control gust");if(id.equals("sv3-5_en_159"))check(m.benchPokemonView(A).getFirst().attachedEnergyIds().size()==count,"Energy Sticker outcome did not control attachment");}check(heads&&tails,"Both coin branches not covered "+id);}}
    static void mill(){var m=game("me3_en_074");var deck=m.privateView(A).deck();var top=List.copyOf(deck.subList(deck.size()-2,deck.size()));play(m);check(m.privateView(A).discard().containsAll(top)&&m.privateView(A).deck().size()==deck.size()-2,"Own top-deck discard wrong owner/order");}
    static ServerMatch fixture(TrainerProfile trainer,int firstSeed,EnergyType energy){return fixture(trainer,firstSeed,energy,GeneratedRuleBatch8Test.trainer("xy2_en_093"));}
    static ServerMatch fixture(TrainerProfile trainer,int firstSeed,EnergyType energy,TrainerProfile supporter){
        var abilities=List.<AbilityDefinition>of();var type=energy;var tags=Map.<String,Set<EnergyType>>of();var attack=GeneratedRuleBatch8Test.hit(100,false);
        String[] ids={"basic","basic","basic","basic","energy","energy","wrong","special","tool","supporter","stadium","item","trainer","evolved","rulebox"};
        var defs=new ArrayList<CardDefinition>();
        for(String id:Arrays.stream(ids).distinct().toList()){
            boolean pokemon=Set.of("basic","evolved","rulebox").contains(id),isEnergy=Set.of("energy","wrong","special").contains(id);
            defs.add(new CardDefinition(id,id,pokemon?CardCategory.POKEMON:isEnergy?CardCategory.ENERGY:CardCategory.TRAINER,
                id.equals("trainer")?trainer.category():id.equals("tool")?TrainerCategory.TOOL:id.equals("supporter")?TrainerCategory.SUPPORTER:id.equals("stadium")?TrainerCategory.STADIUM:id.equals("item")?TrainerCategory.ITEM:TrainerCategory.NONE,"H",Set.of("international"),
                id.equals("basic")||id.equals("rulebox"),id.equals("energy")||id.equals("wrong"),60,Map.of(),EffectSupport.SUPPORTED,null,
                id.equals("rulebox")?Set.of(PokemonFamily.EX,PokemonFamily.RULE_BOX):Set.of(),pokemon?tags.getOrDefault(id,Set.of(id.equals("evolved")?EnergyType.PSYCHIC:type)):Set.of()));
        }
        var pokemon=new HashMap<String,PokemonProfile>();
        for(String id:List.of("basic","evolved","rulebox"))pokemon.put(id,new PokemonProfile(500,1,id.equals("evolved")?"basic":null,null,0,null,0,
            id.equals("rulebox")?2:1,List.of(id.equals("rulebox")?GeneratedRuleBatch8Test.hit(100,false):attack),id.equals("rulebox")?List.of():abilities,id.equals("evolved")?EnergyType.PSYCHIC:type));
        var combat=new CombatCatalog(pokemon,Map.of("energy",energy,"wrong",energy==EnergyType.FIRE?EnergyType.WATER:EnergyType.FIRE),
            Map.of("trainer",trainer,"tool",DynamicPassiveModifierTest.plainTool(),"supporter",supporter,"stadium",GeneratedRuleBatch8Test.trainer("swsh5_en_138"),"item",GeneratedRuleBatch8Test.trainer("swsh5_en_124")),Map.of("special",EnergyProfile.fixed(energy,2)));
        for(int seed=firstSeed;seed<firstSeed+500;seed++){
            var decks=new ArrayList<List<CardInstance>>();for(UUID owner:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(owner.getLeastSignificantBits(),i+1),owner,ids[i%ids.length]));decks.add(cards);}
            var m=new ServerMatch(A,B,decks.get(0),decks.get(1),RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(List.of(A,B).stream().anyMatch(p->{var basics=m.privateView(p).hand().stream().filter(c->m.cardDefinition(c.definitionId()).basicPokemon()).toList();return basics.size()<2||basics.subList(0,2).stream().anyMatch(c->!c.definitionId().equals("basic"));}))continue;
            OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,28);m.drawCardsByEffect(A,B,28);m.endTurn(A);m.endTurn(B);
            if(List.of(A,B).stream().allMatch(p->Arrays.stream(ids).allMatch(id->m.privateView(p).hand().stream().anyMatch(c->c.definitionId().equals(id))))&&
                m.privateView(A).hand().stream().filter(c->c.definitionId().equals("energy")).count()>=3&&m.privateView(A).hand().stream().filter(c->c.definitionId().equals("tool")).count()>=2)return m;
        }throw new AssertionError("No batch 23 fixture");
    }


}
